print(f"Total articles to add: {len(nov26_articles)}")

# Verify character count >= 2000 for each
for a in nov26_articles:
    total_chars = sum(len(p) for p in a['content'])
    print(f"[{a['categoryId']}] {a['title'][:50]}... -> {total_chars} chars (Valid: {total_chars >= 2000})")
    assert total_chars >= 2000, f"Article {a['id']} has only {total_chars} chars!"

print("\nAll 9 articles strictly exceed 2000 characters!")

# Now insert into src/data/articles.ts before the first nov25 article
with open('src/data/articles.ts', 'r', encoding='utf-8') as f:
    ts = f.read()

marker = '"id": "art-2026-11-25-trump-appoints-jamieson-greer-ustr-kevin-hassett-nec"'
insert_idx = ts.find(marker)
object_start_idx = ts.rfind('  {', 0, insert_idx)
print(f"Insert index determined: {object_start_idx}")

# Format articles JSON without outermost brackets
formatted_arts = json.dumps(nov26_articles, indent=2, ensure_ascii=False)
formatted_arts = formatted_arts.strip()[1:-1].strip() + ",\n"

new_ts = ts[:object_start_idx] + formatted_arts + ts[object_start_idx:]

with open('src/data/articles.ts', 'w', encoding='utf-8') as f:
    f.write(new_ts)

print("SUCCESS: Inserted all 9 new articles into src/data/articles.ts!")
